const graph = (nodes: FlowNode[], links: [string, string, string?][]): Definition => ({ schemaVersion: 5, nodes: nodes.map((node, index) => ({ ...node, y: 30 + index * 135 })), edges: links.map(([source, target, branch], index) => ({ id: `e${index}`, source, target, ...(branch ? { branch } : {}) })) });
